/bin/bash -lc "python3 - <<'PY'
import urllib.request,concurrent.futures
base='https://raw.githubusercontent.com/NVIDIA/cuda-samples/db3eea23946bca2e90a75eca2b5b3e07158a9e11/'
paths=['Samples/5_Domain_Specific/MonteCarloMultiGPU/'+p for p in ['MonteCarloMultiGPU.cpp','MonteCarlo_kernel.cu','MonteCarlo_common.h','realtype.h','CMakeLists.txt','README.md']]+['README.md']
def read(p):
 try:
  s=urllib.request.urlopen(base+p,timeout=30).read().decode()
  if p.endswith('.cpp'): lines=[(i,l) for i,l in enumerate(s.splitlines(),1) if i<225 or i>=265]
  elif p.endswith('.cu'): lines=list(enumerate(s.splitlines(),1))
  else: lines=list(enumerate(s.splitlines(),1))
  return p+'\\n'+'\\n'.join(f'{i}: {l}' for i,l in lines)
 except Exception as e:return p+' '+str(e)
with concurrent.futures.ThreadPoolExecutor(max_workers=7) as ex:
 for result in ex.map(read,paths):print(result)
PY"

