51: // Preprocessed input option data
52: typedef struct {
53:   real S;
54:   real X;
55:   real MuByT;
56:   real VBySqrtT;
57: } __TOptionData;
58: 
59: ////////////////////////////////////////////////////////////////////////////////
60: // Overloaded shortcut payoff functions for different precision modes
61: ////////////////////////////////////////////////////////////////////////////////
62: __device__ inline float endCallValue(float S, float X, float r, float MuByT,
63:                                      float VBySqrtT) {
64:   float callValue = S * __expf(MuByT + VBySqrtT * r) - X;
65:   return (callValue > 0.0F) ? callValue : 0.0F;
66: }
67: 
68: __device__ inline double endCallValue(double S, double X, double r,
69:                                       double MuByT, double VBySqrtT) {
70:   double callValue = S * exp(MuByT + VBySqrtT * r) - X;
71:   return (callValue > 0.0) ? callValue : 0.0;
72: }
73: 
74: #define THREAD_N 256
75: 
76: ////////////////////////////////////////////////////////////////////////////////
77: // This kernel computes the integral over all paths using a single thread block
78: // per option. It is fastest when the number of thread blocks times the work per
79: // block is high enough to keep the GPU busy.
80: ////////////////////////////////////////////////////////////////////////////////
81: static __global__ void MonteCarloOneBlockPerOption(
82:     curandState *__restrict rngStates,
83:     const __TOptionData *__restrict d_OptionData,
84:     __TOptionValue *__restrict d_CallValue, int pathN, int optionN) {
85:   // Handle to thread block group
86:   cg::thread_block cta = cg::this_thread_block();
87:   cg::thread_block_tile<32> tile32 = cg::tiled_partition<32>(cta);
88: 
89:   const int SUM_N = THREAD_N;
90:   __shared__ real s_SumCall[SUM_N];
91:   __shared__ real s_Sum2Call[SUM_N];
92: 
93:   // determine global thread id
94:   int tid = threadIdx.x + blockIdx.x * blockDim.x;
95: 
96:   // Copy random number state to local memory for efficiency
97:   curandState localState = rngStates[tid];
98:   for (int optionIndex = blockIdx.x; optionIndex < optionN;
99:        optionIndex += gridDim.x) {
100:     const real S = d_OptionData[optionIndex].S;
101:     const real X = d_OptionData[optionIndex].X;
102:     const real MuByT = d_OptionData[optionIndex].MuByT;
103:     const real VBySqrtT = d_OptionData[optionIndex].VBySqrtT;
104: 
105:     // Cycle through the entire samples array:
106:     // derive end stock price for each path
107:     // accumulate partial integrals into intermediate shared memory buffer
108:     for (int iSum = threadIdx.x; iSum < SUM_N; iSum += blockDim.x) {
109:       __TOptionValue sumCall = {0, 0};
110: 
111: #pragma unroll 8
112:       for (int i = iSum; i < pathN; i += SUM_N) {
113:         real r = curand_normal(&localState);
114:         real callValue = endCallValue(S, X, r, MuByT, VBySqrtT);
115:         sumCall.Expected += callValue;
116:         sumCall.Confidence += callValue * callValue;
117:       }
118: 
119:       s_SumCall[iSum] = sumCall.Expected;
120:       s_Sum2Call[iSum] = sumCall.Confidence;
121:     }
122: 
123:     // Reduce shared memory accumulators
124:     // and write final result to global memory
125:     cg::sync(cta);
126:     sumReduce<real, SUM_N, THREAD_N>(s_SumCall, s_Sum2Call, cta, tile32,
127:                                      &d_CallValue[optionIndex]);
128:   }
129: }
130: 
131: static __global__ void rngSetupStates(curandState *rngState, int device_id) {
132:   // determine global thread id
133:   int tid = threadIdx.x + blockIdx.x * blockDim.x;
134:   // Each threadblock gets different seed,
135:   // Threads within a threadblock get different sequence numbers
136:   curand_init(blockIdx.x + gridDim.x * device_id, threadIdx.x, 0,
137:               &rngState[tid]);
138: }
139: 
140: ////////////////////////////////////////////////////////////////////////////////
141: // Host-side interface to GPU Monte Carlo
142: ////////////////////////////////////////////////////////////////////////////////
143: 
144: extern "C" void initMonteCarloGPU(TOptionPlan *plan) {
145:   checkCudaErrors(cudaMalloc(&plan->d_OptionData,
146:                              sizeof(__TOptionData) * (plan->optionCount)));
147:   checkCudaErrors(cudaMalloc(&plan->d_CallValue,
148:                              sizeof(__TOptionValue) * (plan->optionCount)));
149:   checkCudaErrors(cudaMallocHost(&plan->h_OptionData,
150:                                  sizeof(__TOptionData) * (plan->optionCount)));
151:   // Allocate internal device memory
152:   checkCudaErrors(cudaMallocHost(&plan->h_CallValue,
153:                                  sizeof(__TOptionValue) * (plan->optionCount)));
154:   // Allocate states for pseudo random number generators
155:   checkCudaErrors(cudaMalloc((void **)&plan->rngStates,
156:                              plan->gridSize * THREAD_N * sizeof(curandState)));
157:   checkCudaErrors(cudaMemset(plan->rngStates, 0,
158:                              plan->gridSize * THREAD_N * sizeof(curandState)));
159: 
160:   // place each device pathN random numbers apart on the random number sequence
161:   rngSetupStates<<<plan->gridSize, THREAD_N>>>(plan->rngStates, plan->device);
162:   getLastCudaError("rngSetupStates kernel failed.\n");
163: }
164: 
165: // Compute statistics and deallocate internal device memory
166: extern "C" void closeMonteCarloGPU(TOptionPlan *plan) {
167:   for (int i = 0; i < plan->optionCount; i++) {
168:     const double RT = plan->optionData[i].R * plan->optionData[i].T;
169:     const double sum = plan->h_CallValue[i].Expected;
170:     const double sum2 = plan->h_CallValue[i].Confidence;
171:     const double pathN = plan->pathN;
172:     // Derive average from the total sum and discount by riskfree rate
173:     plan->callValue[i].Expected = (float)(exp(-RT) * sum / pathN);
174:     // Standard deviation
175:     double stdDev = sqrt((pathN * sum2 - sum * sum) / (pathN * (pathN - 1)));
176:     // Confidence width; in 95% of all cases theoretical value lies within these
177:     // borders
178:     plan->callValue[i].Confidence =
179:         (float)(exp(-RT) * 1.96 * stdDev / sqrt(pathN));
180:   }
181: 
182:   checkCudaErrors(cudaFree(plan->rngStates));
183:   checkCudaErrors(cudaFreeHost(plan->h_CallValue));
184:   checkCudaErrors(cudaFreeHost(plan->h_OptionData));
185:   checkCudaErrors(cudaFree(plan->d_CallValue));
186:   checkCudaErrors(cudaFree(plan->d_OptionData));
187: }
188: 
189: // Main computations
190: extern "C" void MonteCarloGPU(TOptionPlan *plan, cudaStream_t stream) {
191:   __TOptionValue *h_CallValue = plan->h_CallValue;
192: 
193:   if (plan->optionCount <= 0 || plan->optionCount > MAX_OPTIONS) {
194:     printf("MonteCarloGPU(): bad option count.\n");
195:     return;
196:   }
197: 
198:   __TOptionData *h_OptionData = (__TOptionData *)plan->h_OptionData;
199: 
200:   for (int i = 0; i < plan->optionCount; i++) {
201:     const double T = plan->optionData[i].T;
202:     const double R = plan->optionData[i].R;
203:     const double V = plan->optionData[i].V;
204:     const double MuByT = (R - 0.5 * V * V) * T;
205:     const double VBySqrtT = V * sqrt(T);
206:     h_OptionData[i].S = (real)plan->optionData[i].S;
207:     h_OptionData[i].X = (real)plan->optionData[i].X;
208:     h_OptionData[i].MuByT = (real)MuByT;
209:     h_OptionData[i].VBySqrtT = (real)VBySqrtT;
210:   }
211: 
212:   checkCudaErrors(cudaMemcpyAsync(plan->d_OptionData, h_OptionData,
213:                                   plan->optionCount * sizeof(__TOptionData),
214:                                   cudaMemcpyHostToDevice, stream));
215: 
216:   MonteCarloOneBlockPerOption<<<plan->gridSize, THREAD_N, 0, stream>>>(
217:       plan->rngStates, (__TOptionData *)(plan->d_OptionData),
218:       (__TOptionValue *)(plan->d_CallValue), plan->pathN, plan->optionCount);
219:   getLastCudaError("MonteCarloOneBlockPerOption() execution failed\n");
220: 
221:   checkCudaErrors(cudaMemcpyAsync(h_CallValue, plan->d_CallValue,
222:                                   plan->optionCount * sizeof(__TOptionValue),
223:                                   cudaMemcpyDeviceToHost, stream));
224: 
225:   // cudaDeviceSynchronize();
226: }
