76: ////////////////////////////////////////////////////////////////////////////////
77: // This kernel computes the integral over all paths using a single thread block
78: // per option. It is fastest when the number of thread blocks times the work per
79: // block is high enough to keep the GPU busy.
80: ////////////////////////////////////////////////////////////////////////////////
81: static __global__ void MonteCarloOneBlockPerOption(
82:     curandState *__restrict rngStates,
83:     const __TOptionData *__restrict d_OptionData,
84:     __TOptionValue *__restrict d_CallValue, int pathN, int optionN) {
85:   // Handle to thread block group
86:   cg::thread_block cta = cg::this_thread_block();
87:   cg::thread_block_tile<32> tile32 = cg::tiled_partition<32>(cta);
88: 
89:   const int SUM_N = THREAD_N;
90:   __shared__ real s_SumCall[SUM_N];
91:   __shared__ real s_Sum2Call[SUM_N];
92: 
93:   // determine global thread id
94:   int tid = threadIdx.x + blockIdx.x * blockDim.x;
95: 
96:   // Copy random number state to local memory for efficiency
97:   curandState localState = rngStates[tid];
98:   for (int optionIndex = blockIdx.x; optionIndex < optionN;
99:        optionIndex += gridDim.x) {
100:     const real S = d_OptionData[optionIndex].S;
101:     const real X = d_OptionData[optionIndex].X;
102:     const real MuByT = d_OptionData[optionIndex].MuByT;
103:     const real VBySqrtT = d_OptionData[optionIndex].VBySqrtT;
104: 
105:     // Cycle through the entire samples array:
106:     // derive end stock price for each path
107:     // accumulate partial integrals into intermediate shared memory buffer
108:     for (int iSum = threadIdx.x; iSum < SUM_N; iSum += blockDim.x) {
109:       __TOptionValue sumCall = {0, 0};
110: 
111: #pragma unroll 8
112:       for (int i = iSum; i < pathN; i += SUM_N) {
113:         real r = curand_normal(&localState);
114:         real callValue = endCallValue(S, X, r, MuByT, VBySqrtT);
115:         sumCall.Expected += callValue;
116:         sumCall.Confidence += callValue * callValue;
117:       }
118: 
119:       s_SumCall[iSum] = sumCall.Expected;
120:       s_Sum2Call[iSum] = sumCall.Confidence;
121:     }
122: 
123:     // Reduce shared memory accumulators
124:     // and write final result to global memory
125:     cg::sync(cta);
126:     sumReduce<real, SUM_N, THREAD_N>(s_SumCall, s_Sum2Call, cta, tile32,
127:                                      &d_CallValue[optionIndex]);
128:   }
129: }
